package com.campus.platform.controller;
import com.campus.platform.service.AuthService; import jakarta.validation.constraints.NotBlank; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/auth") @CrossOrigin public class AuthController { private final AuthService auth; public AuthController(AuthService auth){this.auth=auth;} public record Login(@NotBlank String username,@NotBlank String password){} @PostMapping("/login") public ResponseEntity<?> login(@RequestBody Login req){try{return ResponseEntity.ok(auth.login(req.username(),req.password()));}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}} @PostMapping("/register") public ResponseEntity<?> register(@RequestBody Login req){try{auth.register(req.username(),req.password());return ResponseEntity.ok(Map.of("message","注册成功"));}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}} }
